"""Persistent isolated-package equivalence and recording resource soak."""
import argparse
import gc
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys
import tempfile
import threading
import time
import tracemalloc

ROOT=Path(__file__).absolute().parent

def resource():
    rss=int(next(x.split()[1] for x in Path('/proc/self/status').read_text().splitlines() if x.startswith('VmRSS:')))*1024
    return dict(rss_bytes=rss,fd=len(list(Path('/proc/self/fd').iterdir())),writer_threads=sum(t.name.startswith('episode-writer') for t in threading.enumerate()),traced_current_bytes=tracemalloc.get_traced_memory()[0])

def worker():
    import numpy as np
    import embodiedforge
    from embodiedforge import Config, VectorEnv
    from embodiedforge.data import EpisodeRecorder,read_episodes
    from embodiedforge.rollout import run_rollout
    package=Path(embodiedforge.__file__).parent
    files={str(p.relative_to(package)):hashlib.sha256(p.read_bytes()).hexdigest() for p in package.rglob('*.py')}
    tracemalloc.start()
    initial=resource()
    print(json.dumps(dict(ready=True,package=str(package),source_sha256=files,initial=initial)),flush=True)
    def update(h,arrays):
        for key,value in sorted(arrays.items()):
            h.update(key.encode());h.update(str((value.shape,value.dtype.str)).encode());h.update(np.ascontiguousarray(value).data)
    for line in sys.stdin:
        request=json.loads(line)
        if request.get('quit'):break
        g=request['group'];n=(1,3,16)[g%3];size=(32,64,128,257,540)[(g//3)%5];channels=((),('rgb',),('rgb','depth'))[(g//15)%3]
        if size>=257:n=min(n,3)
        cfg=Config(task=('reach','hold')[(g//45)%2],num_envs=n,max_steps=(1,3,20)[(g//90)%3],seed=5000000+g,render='raster' if channels else 'null',channels=channels,image_size=size)
        steps=(2,7,40)[(g//270)%3];horizon=(1,4)[(g//810)%2];workers=g%3;fmt=('compact','transitions')[(g//3)%2]
        h=hashlib.sha256();transitions=0;callbacks=[]
        with tempfile.TemporaryDirectory(prefix='ef-round5-soak-') as d:
            with VectorEnv(cfg) as env:
                with EpisodeRecorder(Path(d)/'run',env,write_workers=workers,episode_format=fmt,max_buffer_bytes=384*1024*1024) as recorder:
                    class Capture:
                        def append(self,observation,result):
                            nonlocal transitions
                            update(h,observation);update(h,result.observation);update(h,result.info)
                            update(h,dict(reward=result.reward,terminated=result.terminated,truncated=result.truncated))
                            transitions+=int(result.info['active'].sum());recorder.append(observation,result)
                    class Policy:
                        def act(self,observation):return np.repeat(env.task.expert_action(observation)[:,None,:],horizon,axis=1)
                    summary=run_rollout(env,Policy(),steps=steps,chunk_horizon=horizon,writer=Capture(),on_reset=lambda ids:callbacks.append(ids.tolist()))
                    update(h,env.observe())
                decoded=hashlib.sha256();episodes=0
                for episode in read_episodes(Path(d)/'run'):
                    update(decoded,episode);episodes+=1
                    del episode
            del env,recorder
        gc.collect();state=resource()
        assert state['writer_threads']==0 and state['fd']<=initial['fd']+2,state
        identity=dict(summary=vars(summary),callbacks=callbacks,transition_sha256=h.hexdigest(),episode_sha256=decoded.hexdigest(),episodes=episodes,transitions=transitions)
        print(json.dumps(dict(group=g,identity=identity,resources=state)),flush=True)

def parent(until):
    started=time.time();children=[];logs=[];groups=transitions=episodes=0;samples=[];hellos={}
    try:
        for v in ['baseline','candidate']:
            log=(ROOT/f'rollout-soak-socket-final-{v}.stderr').open('w');logs.append(log)
            env=dict(os.environ,PYTHONPATH=str(ROOT/('baseline' if v=='baseline' else 'socket-final-candidate')/'src'))
            child=subprocess.Popen([sys.executable,str(Path(__file__).absolute()),'--worker'],env=env,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=log,text=True,bufsize=1)
            children.append(child);hellos[v]=json.loads(child.stdout.readline());assert hellos[v]['ready']
        while time.time()<until:
            request=json.dumps(dict(group=groups))+'\n'
            for child in children:child.stdin.write(request);child.stdin.flush()
            results=[json.loads(child.stdout.readline()) for child in children]
            assert results[0]['identity']==results[1]['identity'],results
            groups+=1;transitions+=2*results[0]['identity']['transitions'];episodes+=2*results[0]['identity']['episodes']
            if not samples or time.time()-samples[-1]['epoch']>=30:
                sample=dict(epoch=time.time(),groups=groups,resources={v:x['resources'] for v,x in zip(hellos,results)})
                samples.append(sample)
                progress=dict(status='running',started_epoch=started,elapsed_seconds=time.time()-started,paired_groups=groups,combined_rollouts=2*groups,combined_transitions=transitions,combined_episodes=episodes,last=sample)
                tmp=ROOT/'rollout-soak-socket-final-progress.tmp';tmp.write_text(json.dumps(progress,indent=2)+'\n');tmp.replace(ROOT/'rollout-soak-socket-final-progress.json');print(json.dumps(progress),flush=True)
        for child in children:child.stdin.write('{"quit":true}\n');child.stdin.flush()
        for child in children:assert child.wait(timeout=20)==0
        report=dict(status='passed',started_epoch=started,ended_epoch=time.time(),elapsed_seconds=time.time()-started,paired_groups=groups,combined_rollouts=2*groups,combined_transitions=transitions,combined_episodes=episodes,per_source_transitions=transitions//2,per_source_episodes=episodes//2,source_provenance=hellos,samples=samples,scope='Independent persistent complete baseline/candidate packages; exact all-transition/decoded-episode/action/callback/final-state identity. Task reach/hold, N1/3/16 capped 3 for large images, channels none/RGB/RGBdepth, size32/64/128/257/540, timeout1/3/20, steps2/7/40, horizon1/4, writers0/1/2, compact/legacy. Temporary datasets removed each group; fd/writer threads checked each group. Traced allocations are not a hard RSS bound or leak proof.')
        (ROOT/'rollout-soak-socket-final.json').write_text(json.dumps(report,indent=2)+'\n')
    except BaseException as e:
        (ROOT/'rollout-soak-socket-final-failure.json').write_text(json.dumps(dict(error=repr(e),groups=groups),indent=2)+'\n');raise
    finally:
        for child in children:
            if child.poll() is None:
                child.terminate()
                try:child.wait(timeout=10)
                except subprocess.TimeoutExpired:child.kill();child.wait()
        for log in logs:log.close()

p=argparse.ArgumentParser();p.add_argument('--worker',action='store_true');p.add_argument('--until',type=float,default=1792044000);a=p.parse_args()
if a.worker:worker()
else:parent(a.until)

