"""Differential custom-field/ownership/validation exercise against pre-cache writer."""
import gc,hashlib,importlib.util,json,sys,tempfile,time
from pathlib import Path
import numpy as np
from embodiedforge import Config,VectorEnv
from embodiedforge.data import EpisodeRecorder,read_episodes
r=Path(__file__).absolute().parent
spec=importlib.util.spec_from_file_location('embodiedforge._round5_old_data',r/'before-recorder/src/embodiedforge/data.py')
baseline=importlib.util.module_from_spec(spec);sys.modules[spec.name]=baseline;spec.loader.exec_module(baseline)
started=time.time();digest=hashlib.sha256();groups=episodes=transitions=retries=inactive_batches=0;coverage={}
dtypes=[np.dtype('f4'),np.dtype('>f4'),np.dtype('<i2'),np.dtype('>i2'),np.dtype('u1'),np.dtype('?')]

def extra(n,step,group):
    dtype=dtypes[group%len(dtypes)]
    base=(np.arange(n*6).reshape(n,2,3)+step)%7
    array=base.astype(dtype)
    mode=(group//6)%3
    if mode==1:array=np.asfortranarray(array)
    if mode==2:array=array[:,:,::-1]
    return {'feature/坐标':array,'confidence':np.full(n,step/100,dtype=np.float64),'event':np.full(n,step%2,dtype=bool)}

def update(h,episode):
    for key,value in episode.items():
        h.update(key.encode());h.update(str((value.shape,value.dtype.str)).encode());h.update(value.tobytes())

try:
 for group in range(2000):
    n=(1,3,8)[(group//18)%3];steps=(1,3,10)[(group//54)%3];workers=(group//162)%3;fmt=('compact','transitions')[(group//486)%2]
    key=f'{n}:{steps}:{workers}:{fmt}:{dtypes[group%6].str}:{(group//6)%3}';coverage[key]=coverage.get(key,0)+1
    with tempfile.TemporaryDirectory(prefix='ef-recorder-fields-') as directory,VectorEnv(Config(task='hold',num_envs=n,max_steps=steps)) as env:
        writers=[cls(Path(directory)/variant,env,episode_format=fmt,write_workers=workers) for cls,variant in [(baseline.EpisodeRecorder,'baseline'),(EpisodeRecorder,'candidate')]]
        try:
            for step in range(steps):
                observation=env.observe();observation.update(extra(n,step,group))
                result=env.step(np.zeros((n,2)));result.observation.update(extra(n,step+1,group))
                # Independent key orders must retain the original archive order.
                if group%2:observation=dict(reversed(tuple(observation.items())))
                if step%2:result.observation=dict(reversed(tuple(result.observation.items())))
                if step>0:
                    bad={name:value.copy() for name,value in observation.items()}
                    bad['confidence'][0]+=1
                    errors=[]
                    for writer in writers:
                        before=(writer.buffered_bytes,{k:len(v) for k,v in writer.pending.items()})
                        try:writer.append(bad,result)
                        except ValueError as error:errors.append((type(error).__name__,str(error)))
                        else:raise AssertionError('corrupted continuation accepted')
                        assert before==(writer.buffered_bytes,{k:len(v) for k,v in writer.pending.items()})
                        assert writer.failure is None
                    assert errors[0]==errors[1];retries+=2
                for writer in writers:writer.append(observation,result)
                # Returned arrays remain caller-owned and mutable after append.
                for value in [*observation.values(),*result.observation.values()]:value[...] = 0
                result.reward[:]=0
            for _ in range(2):
                observation=env.observe();observation.update(extra(n,steps,group))
                result=env.step(np.zeros((n,2)));result.observation.update(extra(n,steps,group))
                assert not result.info['active'].any()
                for writer in writers:writer.append(observation,result)
                inactive_batches+=2
        finally:
            for writer in writers:writer.close()
        left=read_episodes(Path(directory)/'baseline');right=read_episodes(Path(directory)/'candidate')
        for expected,actual in zip(left,right,strict=True):
            assert tuple(expected)==tuple(actual)
            for name in expected:np.testing.assert_array_equal(actual[name],expected[name])
            update(digest,actual);episodes+=2;transitions+=2*len(actual['action'])
        for writer in writers:assert writer.closed and writer.buffered_bytes==0 and not writer._writes
    groups+=1;gc.collect()
    if groups%100==0:
        progress=dict(status='running',groups=groups,elapsed_seconds=time.time()-started,combined_episodes=episodes,combined_transitions=transitions,rejected_retry_batches=retries,inactive_batches=inactive_batches)
        (r/'recorder-fields-progress.json').write_text(json.dumps(progress,indent=2)+'\n');print(json.dumps(progress),flush=True)
 report=dict(status='passed',groups=groups,elapsed_seconds=time.time()-started,combined_episodes=episodes,combined_transitions=transitions,rejected_retry_batches=retries,inactive_batches=inactive_batches,coverage=coverage,decoded_candidate_sequence_sha256=digest.hexdigest(),baseline_data_sha256=hashlib.sha256(Path(baseline.__file__).read_bytes()).hexdigest(),candidate_data_sha256=hashlib.sha256((r.parent.parent/'src/embodiedforge/data.py').read_bytes()).hexdigest(),scope='Shared unchanged env/validators, pre-field-cache5f EpisodeRecorder versus final writer. N1/3/8, length1/3/10, writers0/1/2, compact/legacy, f4/non-nativef4/i2/non-nativei2/u1/bool extra fields, C/Fortran/negative-stride views, Unicode/slash field names and independent obs/result field order. Every decoded field/key order matches. Mutate all caller observations after append; corrupt continuation then retry correct input with unchanged pending bytes/rows; inactive batches do not write episodes. Counts are combined across both writers, while SHA covers candidate sequence only.')
 (r/'recorder-fields-check.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({k:v for k,v in report.items() if k!='coverage'}),flush=True)
except BaseException as error:
 (r/'recorder-fields-failure.json').write_text(json.dumps(dict(error=repr(error),groups=groups),indent=2)+'\n');raise
